INSERT INTO `tagihan_template_whatsapp` VALUES (5, 'Bukti Pembayaran', 'Bukti Pembayaran', 'Bismillahirrahmanirrahim.\r\nYth. Bapak/Ibu {nama_wali}, pembayaran {nama_siswa} sebesar {total_bayar} telah kami terima pada {tanggal}. Nomor transaksi: {no_transaksi}. Terima kasih atas pembayarannya.\r\nJazaakumullahu Khayran.', 'Ya', 'Aktif', '29-09-2026', '07:20:45', 20, 'Nasirudin Albani, S.Pd.');
INSERT INTO `tagihan_template_whatsapp` VALUES (6, 'Surat Tunggakan', 'Surat Tagihan', 'Bismillahirrahmanirrahim.\r\nYth. Bapak/Ibu {nama_wali}, kami memberikan informasi terkait pembayaran {nama_siswa} kelas {kelas} terdapat tunggakan sebesar {total_tunggakan}, mohon kiranya Bapak/Ibu dapat menyelesaikan pembayaran, untuk melihat rincian pembayaran bisa dilakukan melalui akun wali murid. \r\nJika terdapat kesalahan data atau kendala pembayaran, dimohon untuk menghubungi nomor admin. Terima kasih.\r\nJazaakumullahu Khayran.', 'Ya', 'Aktif', '29-09-2026', '07:28:53', 20, 'Nasirudin Albani, S.Pd.');
